-- Dansk portion 2 del 1/3: 167 MC-spørgsmål på sværhedsskalaen 1-10.000, niveau 5-3311.
-- Del af de 5.000 nye danskopgaver. Skrevet fra bunden til dansk folkeskole, 3.-9. klasse.
-- Genereret af tools/questions/build-danish-5000.mjs; ret i tools/questions/fixtures/danish-5000/, ikke her.
-- Kræver migration A (20261020120000_difficulty_scale_a): kolonnen questions.difficulty_level.
--
-- Niveau: hver opgave har et eksplicit difficulty_level (forfatterens skøn, ikke en måling).
-- target_grade/difficulty_band er afledt baglæns af niveauet (cellen i §4.1).
--
-- INAKTIV VED INDSÆTTELSEN: alle rækker får is_active=false og metadata.level_batch='danish2'.
-- Aktivering er en SEPARAT migration efter dokumenteret stikprøvekontrol og særskilt ejergodkendelse.
-- Må KUN anvendes via apply_migration med særskilt ejer-autorisation (D-110).

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band, difficulty_level)
SELECT
  jsonb_build_object('question', e->>'q', 'options', e->'o', 'correct', e->>'a',
                     'accepted_answers', jsonb_build_array(e->>'a'), 'review_text', e->>'r'),
  'mc', 'short',
  jsonb_build_object('concepts', jsonb_build_array(m.concept), 'cognitive_skill', m.skill,
                     'difficulty_type', m.dtype, 'misconception_type', m.mis,
                     'challenge_role', e->>'role', 'insight_type', e->>'insight',
                     'practice_variant', e->>'variant',
                     'level_batch', 'danish2', 'domain', 'danish'),
  'mc_single', (e->>'b')::int, 'auto', false, 'danish', (e->>'g')::int,
  (e->>'b')::int, (e->>'l')::int
FROM jsonb_array_elements($$[
{"l":5,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Emma har en hund. Hunden hedder Bella.' Hvad hedder Emmas hund?","o":["Bella","Molly","Emma","Bobby"],"a":"Bella","r":"Den anden sætning fortæller, at hunden hedder Bella. Emma er pigen, der ejer hunden."},
{"l":23,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Aya bor i et gult hus. Hendes ven Malte bor i et rødt hus.' Hvilken farve har Ayas hus?","o":["Rød","Gul","Blå","Grøn"],"a":"Gul","r":"Der står, at Aya bor i et gult hus. Det røde hus er Maltes."},
{"l":42,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Et glas kan være tomt. Hvad er det modsatte af 'tomt'?","o":["rundt","koldt","fuldt","rent"],"a":"fuldt","r":"Er der ingenting i glasset, er det tomt. Er der så meget, der kan være, er det fuldt."},
{"l":64,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad bruger man en paraply til?","o":["at holde sig varm om vinteren","at sidde på i det våde græs","at vifte sig i varmt vejr","at holde sig tør i regnvejr"],"a":"at holde sig tør i regnvejr","r":"En paraply holder man over hovedet, så regnen ikke rammer en."},
{"l":84,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilken form passer i sætningen: 'To ___ spiller bold i gården.'","o":["drenge","dreng","drengen","drengene"],"a":"drenge","r":"Når der er to, skal ordet stå i flertal: en dreng, to drenge."},
{"l":102,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad kalder man en mor eller en far med ét ord?","o":["nabo","forælder","kusine","fætter"],"a":"forælder","r":"En forælder er en mor eller en far. To af dem kalder man forældre."},
{"l":123,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Vælg det rigtige stedord: 'Kan du hjælpe ___ med tasken?'","o":["jeg","vi","mig","han"],"a":"mig","r":"Det er en anden, der hjælper, og det er 'mig', der får hjælpen. Derfor er det 'mig' og ikke 'jeg'."},
{"l":144,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Emil og Amina bygger en hule i skoven. De bruger grene og blade. Hulen bliver stor nok til dem begge.' Hvad bygger de hulen af?","o":["Sten og jord","Papkasser og tape","Brædder og søm","Grene og blade"],"a":"Grene og blade","r":"Teksten nævner grene og blade. Det er ting, man kan finde i skoven."},
{"l":162,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilket stedord passer: '___ kan godt lide is.'","o":["Hun","Hende","Ham","Os"],"a":"Hun","r":"Den, der gør noget i sætningen, hedder 'hun'. 'Hende', 'ham' og 'os' bruger man, når der sker noget med personen."},
{"l":181,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Find den rigtige stavemåde: 'Der ligger mange sjove ___ i min skuffe.'","o":["tink","ting","tingg","teng"],"a":"ting","r":"Lyden til sidst skrives ng, og der skal ikke et ekstra g med."},
{"l":204,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Efter hvilket ord skal punktummet stå: 'Hunden sover i kurven Katten ligger i vinduet.'?","o":["sover","Katten","kurven","ligger"],"a":"kurven","r":"Efter 'kurven' er den første sætning færdig. Den næste sætning begynder med 'Katten' med stort bogstav."},
{"l":222,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Maja hjælper sin lillebror med at binde snørebånd. Han er kun fire år. Bagefter går de ud og leger.' Hvem er fire år?","o":["Maja","Majas ven","Majas mor","Majas lillebror"],"a":"Majas lillebror","r":"Ordet 'han' i den anden sætning peger på lillebroren. Det er ham, der er fire år."},
{"l":240,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilket ord i sætningen skal skrives med stort: 'Min gode ven hedder ali.'","o":["ali","gode","ven","hedder"],"a":"ali","r":"Ali er navnet på en person. Navne på personer er egennavne og skrives med stort."},
{"l":264,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Det kører på skinner og har mange vogne. Hvordan staves det?","o":["tok","tog","togg","tou"],"a":"tog","r":"Ordet ender på ét g, ligesom 'dag' og 'bog'."},
{"l":282,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket ord kan sættes foran 'bold', så det giver et rigtigt ord?","o":["mave","næse","fod","sko"],"a":"fod","r":"Fodbold er en sport, hvor man sparker til en bold. Det er et sammensat ord af 'fod' og 'bold'."},
{"l":304,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"I et spil kan man vinde. Hvad er det modsatte af at 'vinde'?","o":["spille","løbe","tælle","tabe"],"a":"tabe","r":"Når en vinder, må en anden ofte tabe. Ordene er hinandens modsætninger."},
{"l":322,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Den skinner på himlen om dagen og giver os varme. Hvordan staves den?","o":["sol","soll","sool","soel"],"a":"sol","r":"Danske ord ender sjældent på ll, så der er ét l. O'et er langt, men skrives kun én gang."},
{"l":343,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Anton fandt en tegnebog på fortovet. Han gav den til en voksen i butikken. Ejeren blev meget glad.' Hvad fandt Anton?","o":["En telefon","En tegnebog","En nøgle","En taske"],"a":"En tegnebog","r":"Den første sætning fortæller, at han fandt en tegnebog på fortovet."},
{"l":364,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket ord er det modsatte af 'rig'?","o":["venlig","lav","fattig","ung"],"a":"fattig","r":"En rig person har mange penge. En fattig person har meget få penge."},
{"l":383,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilken form af tillægsordet passer: 'Hun har et ___ tæppe.'","o":["blød","bløde","blødest","blødt"],"a":"blødt","r":"Det hedder et tæppe. Foran et-ord får tillægsordet her et -t: et blødt tæppe."},
{"l":402,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket ord kan man bruge i stedet for 'bange'?","o":["skræmt","modig","trist","rolig"],"a":"skræmt","r":"Den, der er skræmt, er blevet bange for noget. De to ord betyder næsten det samme."},
{"l":422,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Find navneordet i spørgsmålet: 'Hvor er din nye blyant?'","o":["nye","blyant","din","Hvor"],"a":"blyant","r":"En blyant er en ting, og man kan sige 'en blyant'. 'Nye' er et tillægsord, der fortæller, hvordan den er."},
{"l":444,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilket ord mangler stort bogstav: 'Noah og oskar spiller fodbold.'?","o":["og","spiller","oskar","fodbold"],"a":"oskar","r":"Oskar er et navn ligesom Noah, så det skal også have stort bogstav."},
{"l":462,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad er et bibliotek?","o":["et sted, hvor man kan købe bøger","et sted, hvor man kan se gamle ting","et sted, hvor man kan se film","et sted, hvor man kan låne bøger"],"a":"et sted, hvor man kan låne bøger","r":"På biblioteket låner man bøger gratis og afleverer dem igen bagefter. Købe bøger gør man i en boghandel."},
{"l":482,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Frederik har fået en kat, der hedder Plet. Plet er sort med en hvid plet på næsen.' Hvorfor hedder katten nok Plet?","o":["Fordi den har en hvid plet","Fordi Frederik kan lide det","Fordi den er meget sort","Fordi den er meget lille"],"a":"Fordi den har en hvid plet","r":"Navnet ligner det, man kan se på katten: en hvid plet på næsen."},
{"l":500,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilket ord skal skrives med stort: 'Vi bor i aalborg og har en lille have.'","o":["have","aalborg","lille","bor"],"a":"aalborg","r":"Aalborg er navnet på en by. Navne på byer er egennavne og skrives med stort."},
{"l":522,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Verdens største dyr lever i havet. Hvilken stavemåde er rigtig?","o":["vall","hvall","hval","hvaal"],"a":"hval","r":"Dyret begynder med hv. Ordet slutter på ét l, fordi a'et er langt."},
{"l":540,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilken sætning om cyklen skal slutte med spørgsmålstegn?","o":["Den røde cykel er ny","Jeg låste min cykel","Min cykel står i gården","Hvem ejer den røde cykel"],"a":"Hvem ejer den røde cykel","r":"Sætningen begynder med spørgeordet 'hvem', og man vil have et svar. De andre sætninger fortæller noget."},
{"l":564,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Du kan sidde på den i parken. Hvordan staves den?","o":["bænk","bæng","bængk","bænck"],"a":"bænk","r":"Ordet ender med en k-lyd, så der skrives nk."},
{"l":582,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket ord passer: 'Isen er tynd, så du skal være ___.'","o":["modig","forsigtig","glad","tung"],"a":"forsigtig","r":"At være forsigtig er at passe på, så der ikke sker noget farligt."},
{"l":603,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Anna og Marie tegner sammen. Anna tegner et slot, og Marie tegner en ridder. Så klipper de begge dele ud og sætter dem på samme ark.' Hvem tegner ridderen?","o":["Anna","Begge piger","Marie","Annas mor"],"a":"Marie","r":"Der står, at Marie tegner en ridder. Anna tegner slottet."},
{"l":621,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Isabella fik et brev med posten. Der stod hendes navn på, og det var fra hendes kusine i Norge. Hun løb op på sit værelse for at læse det i ro.' Hvor bor Isabellas kusine?","o":["I Danmark","I Sverige","I Tyskland","I Norge"],"a":"I Norge","r":"Der står, at brevet kom fra hendes kusine i Norge."},
{"l":642,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket ord passer: 'Bussen kører om et øjeblik, så vi må ___ os.'","o":["skynde","hygge","kede","more"],"a":"skynde","r":"At skynde sig betyder at gøre noget hurtigt, fordi man ikke har meget tid."},
{"l":664,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad er en turist?","o":["en, der viser andre rundt i byen","en, der rejser for at se nye steder","en, der kører en stor bus","en, der flytter til et nyt land"],"a":"en, der rejser for at se nye steder","r":"En turist er på ferie eller tur et sted, hvor han eller hun ikke bor, og ser sig omkring."},
{"l":681,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Esther ser en edderkop i badekarret. Hun skriger og løber ud på gangen. Far kommer med et glas og et stykke papir.' Hvad vil far nok gøre?","o":["Give edderkoppen vand","Skrive et brev til Esther","Fange edderkoppen og bære den ud","Drikke et glas vand på badeværelset"],"a":"Fange edderkoppen og bære den ud","r":"Med et glas og et stykke papir kan man fange en edderkop og flytte den, så Esther kan komme ind igen."},
{"l":702,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket dyr passer i udtrykket: 'Han er stærk som en ___.'","o":["ræv","ugle","hare","bjørn"],"a":"bjørn","r":"Bjørnen er et stort og kraftigt dyr. Derfor bruger man den, når man vil sige, at nogen er meget stærk."},
{"l":722,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Du bruger det til at fjerne blyant fra papiret. Hvilken stavemåde er rigtig?","o":["viskelæder","viskelæter","hviskelæder","viskelæer"],"a":"viskelæder","r":"Ordet kommer af 'at viske' og 'læder'. Det har intet h, for det har ikke noget med at hviske at gøre."},
{"l":740,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"Hvad kalder man en historie, der fortælles i billeder med talebobler?","o":["et fotoalbum","en tegneserie","en tegnefilm","et eventyr"],"a":"en tegneserie","r":"I en tegneserie fortæller billederne historien. Det, personerne siger, står i talebobler."},
{"l":760,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilket ord passer: 'Jeg børster mine ___ hver aften.'","o":["tand","tanden","tænder","tænderne"],"a":"tænder","r":"Man har mange, så ordet står i flertal: en tand, flere tænder. Efter 'mine' bruger man ikke den bestemte form 'tænderne'."},
{"l":781,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Ugens sidste dag. Hvilket ord er stavet rigtigt?","o":["sønndag","sønda","sømdag","søndag"],"a":"søndag","r":"Ordet har kun ét n, og det slutter på -dag."},
{"l":803,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Alle i klassen havde fået en bolle. Rune tog en bid og spyttede den ud. Læreren havde taget salt i stedet for sukker.' Hvordan smagte bollen?","o":["For salt","For sød","Meget stærk","Af kanel"],"a":"For salt","r":"Læreren havde brugt salt i stedet for sukker, så bollen smagte alt for salt."},
{"l":822,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad kalder man det, når to er gode venner?","o":["en venlighed","et venskab","et fjendskab","et mesterskab"],"a":"et venskab","r":"Endelsen -skab laver navneord. Et venskab er det bånd, der er mellem to venner."},
{"l":839,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Sæt det rigtige ord ind: 'Børnene ___ i sandkassen.'","o":["lege","legger","leger","lejger"],"a":"leger","r":"Her skal nutids-r på. Ordet skrives med ét g, selvom det kan lyde som j."},
{"l":863,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Ingen måtte vide, at Gustav stadig havde sin bamse med på lejrskolen. Han gemte den nederst i soveposen.' Hvorfor gemte Gustav bamsen?","o":["Han var bange for, at den blev beskidt","Han havde lånt den af sin lillebror","Han havde glemt, at han havde den med","Han ville ikke have, at de andre så den"],"a":"Han ville ikke have, at de andre så den","r":"'Ingen måtte vide det' viser, at han var flov. Derfor skjulte han bamsen."},
{"l":881,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Dyret har en lang hale og store bagben. Det hopper rundt i Australien, og ungen bor i moderens pung.' Hvilket dyr handler teksten om?","o":["En kænguru","En hare","En koala","Et egern"],"a":"En kænguru","r":"Store bagben, hop og en pung til ungen passer tilsammen kun på kænguruen. En hare hopper også, men den har ingen pung og bor ikke i Australien."},
{"l":900,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilke tegn sætter man om de ord, en person siger?","o":["parenteser","anførselstegn","kommaer","bindestreger"],"a":"anførselstegn","r":"Anførselstegn viser, hvor det, personen siger, begynder og slutter. Det kaldes direkte tale."},
{"l":922,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvilket ord passer: 'Bogen ___ på bordet.'","o":["lægger","ligge","ligger","legger"],"a":"ligger","r":"Bogen er stille på bordet, så her skal 'ligger' stå. 'Lægger' bruger man, når nogen flytter noget derhen."},
{"l":942,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad kalder man den tid, der endnu ikke er kommet?","o":["fortiden","nutiden","fritiden","fremtiden"],"a":"fremtiden","r":"Fremtiden er det, der kommer. Fortiden er det, der er sket, og nutiden er det, der sker nu."},
{"l":959,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Ronja fik lov til at holde kaninen. Hun sad helt stille og turde næsten ikke trække vejret. Kaninens hjerte bankede hurtigt mod hendes hånd.' Hvorfor sad Ronja så stille?","o":["Hun ville ikke skræmme kaninen","Hun var faldet i søvn","Hun havde ondt i sin hånd","Hun var sur på kaninen"],"a":"Hun ville ikke skræmme kaninen","r":"Kaninen er lille og bange, med et hjerte, der banker hurtigt. Ronja passer på ikke at gøre den mere bange."},
{"l":981,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Malthe er 10 år, og Frida er 12 år. Hvilket ord passer: 'Frida er ___ end Malthe.'","o":["gammel","ældre","gamle","ældst"],"a":"ældre","r":"Der sammenlignes med 'end', så det er højere grad. 'Gammel' skifter ord: gammel, ældre, ældst."},
{"l":1002,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Jern, kobber og sølv hører sammen. Hvad er de alle sammen?","o":["stenarter","væsker","metaller","træsorter"],"a":"metaller","r":"Metaller er hårde og skinnende stoffer, der kan smeltes. Man laver for eksempel mønter og søm af dem."},
{"l":1020,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilken sætning om drikkevarer har rigtige kommaer?","o":["Vil du, have saft mælk eller vand?","Vil du have saft mælk, eller, vand?","Vil du have saft, mælk, eller vand?","Vil du have saft, mælk eller vand?"],"a":"Vil du have saft, mælk eller vand?","r":"Der står komma mellem delene i en opremsning. Foran det sidste 'eller' skal der ikke komma, ligesom foran 'og'."},
{"l":1039,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Sæt det rigtige ord ind: 'Jeg har ikke fået mad i lang tid, så jeg er ___.'","o":["sulten","sultn","sullten","sultæn"],"a":"sulten","r":"Ordet skrives med ét l og slutter på -en."},
{"l":1062,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad gør den, der 'tager benene på nakken'?","o":["laver en kolbøtte","løber hurtigt væk","sidder helt stille","lægger sig og slapper af"],"a":"løber hurtigt væk","r":"Udtrykket bruger man om en, der skynder sig væk, ofte fordi noget er farligt eller pinligt."},
{"l":1081,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Sæt det rigtige ord ind: 'Jeg er ___ med mine lektier.'","o":["ferdig","færdi","færdig","færrdig"],"a":"færdig","r":"Ordet skrives med æ og rd og får endelsen -ig. D'et kan høres, men g'et kan ikke."},
{"l":1098,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilket ord skal have stort begyndelsesbogstav: 'I juli kørte vi til tyskland.'","o":["juli","kørte","vi","tyskland"],"a":"tyskland","r":"Navne på lande er egennavne og skrives med stort. Måneder skrives med småt."},
{"l":1122,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Det mørke bagværk, som mange har i madpakken. Vælg den rigtige stavemåde.","o":["rugbrød","rubrød","rugbrøt","rug brød"],"a":"rugbrød","r":"Ordet består af 'rug' og 'brød'. Det skrives i ét ord, og g'et skal med."},
{"l":1140,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilket ord er forkert skrevet med lille: 'På lørdag spiller Hassan kamp i esbjerg.'?","o":["lørdag","esbjerg","spiller","kamp"],"a":"esbjerg","r":"Esbjerg er et bynavn og skal have stort bogstav. Ugedagen lørdag skrives med lille."},
{"l":1160,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"H.C. Andersen blev født i en by på Fyn. Hvad hedder byen?","o":["Aarhus","Aalborg","Odense","Skagen"],"a":"Odense","r":"Odense ligger på Fyn. Her voksede H.C. Andersen også op, før han som ung rejste til København."},
{"l":1181,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Stedet, hvor små børn går, før de kommer i skole. Hvordan staves det?","o":["bønehave","børnehaue","børne have","børnehave"],"a":"børnehave","r":"Ordet består af 'børne' og 'have' og skrives i ét ord."},
{"l":1201,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Mange fuglehanner synger for at blive hørt af hunnerne. Påfuglehannen gør noget andet. Den slår sin store hale ud som en vifte, og så kigger hunnerne på den.' Hvorfor slår påfuglen halen ud?","o":["For at hunnerne skal se ham","For at køle sig af","For at skræmme insekter væk","For at flyve op i et træ"],"a":"For at hunnerne skal se ham","r":"Andre hanner synger for hunnerne, og påfuglen gør noget andet for at få deres opmærksomhed. Halen får hunnerne til at kigge."},
{"l":1219,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Da Rebecca kom hjem fra lejrskolen, snakkede hun uden pause. Hun fortalte om natløbet, om bålet og om sine nye venner, og hun holdt først inde, da hun skulle spise.' Hvordan har Rebecca haft det på lejrskolen?","o":["Hun har kedet sig","Hun har haft det sjovt","Hun har været syg","Hun har frosset meget"],"a":"Hun har haft det sjovt","r":"Hun snakker uden pause om det, de har lavet, og hun har fået nye venner. Det viser, at det har været sjovt."},
{"l":1240,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"Læs: 'Emil er så hurtig som en hare.' Hvilket lille ord viser, at der er en sammenligning?","o":["er","en","som","hurtig"],"a":"som","r":"Ordet 'som' binder Emil og haren sammen. Emil bliver sammenlignet med en hare, fordi de begge er hurtige."},
{"l":1260,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Efter hvilket ord mangler kommaet: 'Det regner blæser og sner i dag.'?","o":["Det","blæser","sner","regner"],"a":"regner","r":"Vejret gør tre ting, og dem opremser man med komma. Foran 'og' skal der ikke komma."},
{"l":1280,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Vælg den rigtige form: 'Hun sov under et ___ tæppe.'","o":["gammelt","gammel","gamle","ældst"],"a":"gammelt","r":"Det hedder et tæppe, så der kommer -t på: et gammelt tæppe."},
{"l":1302,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad betyder ordsproget 'Man skal ikke skue hunden på hårene'?","o":["at man skal børste sin hund hver eneste dag","at man ikke kan se på nogen, hvordan de er","at man ikke må kigge for længe på fremmede dyr","at hunde med langt hår er bedre end andre hunde"],"a":"at man ikke kan se på nogen, hvordan de er","r":"At skue betyder at se. Selv om noget ser mærkeligt ud, kan det være godt indeni."},
{"l":1320,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"Læs: 'Kære mormor. Tak for gaven. Mange hilsner fra Sofie.' Hvilken slags tekst er det?","o":["et eventyr","et digt","et brev","en opskrift"],"a":"et brev","r":"Et brev begynder ofte med 'Kære' og slutter med en hilsen. Det er skrevet til en bestemt person."},
{"l":1339,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Vælg den rigtige stavemåde: 'En mus er ___ end en elefant.'","o":["minre","mindere","minndre","mindre"],"a":"mindre","r":"Ordet bruges, når to ting sammenlignes. Der står et d mellem n og r, og det kan høres."},
{"l":1358,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvor mange navneord er der i sætningen: 'Drengen gav hunden en bold.'","o":["tre","to","fire","ét"],"a":"tre","r":"Navneordene er 'drengen', 'hunden' og 'bold'. Alle tre kan få 'en' foran sig."},
{"l":1381,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Ti gange hundrede giver dette tal. Hvordan staves det?","o":["tusin","tusind","tusint","tussind"],"a":"tusind","r":"Ordet skrives med ét s og ender på stumt d."},
{"l":1400,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"Hvem siger først højt, at kejseren ikke har noget på i 'Kejserens nye klæder'?","o":["kejserens minister","en af væverne","et lille barn","kejseren selv"],"a":"et lille barn","r":"De voksne tør ikke sige sandheden. Barnet siger bare det, det kan se."},
{"l":1422,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad betyder det at 'vedligeholde' sin cykel?","o":["at sælge den til en, der har brug for den","at køre på den hver eneste dag til skolen","at købe en ny, når den gamle er blevet for lille","at passe på den, så den bliver ved med at virke"],"a":"at passe på den, så den bliver ved med at virke","r":"Man vedligeholder en cykel ved at pumpe dækkene og smøre kæden, så den holder længe."},
{"l":1440,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"Med hvilke ord slutter mange eventyr?","o":["Og de levede lykkeligt til deres dages ende","Så var dagen forbi, og alle gik i seng","Fortsættelsen kommer i bladet i næste uge","Tak, fordi du læste min lille tekst i dag"],"a":"Og de levede lykkeligt til deres dages ende","r":"Eventyr ender tit lykkeligt. Det gode vinder, og slutningen fortæller, at alt nu er godt for altid."},
{"l":1460,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket ord ligger tættest på 'snakke' i betydning?","o":["lytte","tale","tænke","kigge"],"a":"tale","r":"At snakke og at tale er næsten det samme, men 'tale' er lidt finere. Når man lytter, er det en anden, der taler."},
{"l":1480,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Du bør have den på hovedet, når du cykler. Hvordan staves den?","o":["jelm","hjælm","hjelm","hjellm"],"a":"hjelm","r":"Ordet begynder med hj og skrives med e. Der er ét l."},
{"l":1499,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Kornet, der bliver til mel i dit brød. Hvilket ord er stavet rigtigt?","o":["vede","hvæde","hvedde","hvede"],"a":"hvede","r":"Kornet begynder med stumt h. Det skrives med e og ét d."},
{"l":1521,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Da Sigrid havde læst brevet færdigt, foldede hun det sammen og kiggede ud ad vinduet. Der gik længe, før hun sagde noget. Så smilede hun og sagde: Vi skal flytte til Aarhus.' Hvad står der nok i brevet?","o":["At familien skal flytte til Aarhus","At hendes mormor flytter til Aarhus","At hun skal på ferie i Aarhus","At hendes skole flytter til Aarhus"],"a":"At familien skal flytte til Aarhus","r":"Når hun har læst brevet, siger hun: Vi skal flytte til Aarhus. 'Vi' er hendes familie, og det må være det, brevet handlede om."},
{"l":1539,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Lyn og torden kommer samtidig, men vi ser lynet først. Det er, fordi lys bevæger sig meget hurtigere end lyd. Derfor kan man høre tordenen flere sekunder senere.' Hvorfor ser vi lynet, før vi hører tordenen?","o":["Fordi tordenen kommer efter lynet","Fordi lyset er hurtigere end lyden","Fordi øjnene er bedre end ørerne","Fordi skyerne stopper lyden"],"a":"Fordi lyset er hurtigere end lyden","r":"Teksten siger, at de kommer samtidig, men at lys bevæger sig hurtigere end lyd."},
{"l":1559,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket ord betyder næsten det samme som 'underlig'?","o":["farlig","ærlig","mærkelig","kedelig"],"a":"mærkelig","r":"Noget underligt er anderledes, end man venter, ligesom noget mærkeligt. De andre ord ender også på -lig, men betyder noget helt andet."},
{"l":1582,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad er et 'skema' i skolen?","o":["en prøve i slutningen af året","en bog med opgaver til dansk","et brev fra læreren til forældrene","en oversigt over ugens timer"],"a":"en oversigt over ugens timer","r":"På skemaet kan du se, hvilke fag du har hvornår i løbet af ugen."},
{"l":1602,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Kaj var den ældste i klubben. Hver onsdag stod han klar ved kaffemaskinen længe før de andre og satte stole frem. Ingen havde bedt ham om det.' Hvad fortæller teksten om Kaj?","o":["At han hjælper uden at blive bedt om det","At han vil have kaffen før de andre","At han bestemmer over de andre i klubben","At han er ny i klubben"],"a":"At han hjælper uden at blive bedt om det","r":"Han kommer før de andre og sætter stole frem, selvom ingen har bedt ham om det."},
{"l":1620,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Hajer mister tit deres tænder, når de bider. Det gør ikke noget, for bag de forreste tænder står der flere rækker nye tænder klar.' Hvad sker der, når en haj mister en tand?","o":["Den må bide med den anden side","En ny tand rykker frem","Den kan ikke længere spise","Tanden vokser fast igen"],"a":"En ny tand rykker frem","r":"Teksten siger, at der står rækker af nye tænder klar. De tager over, når en tand falder ud."},
{"l":1642,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvad skal der stå på stregen? 'Det var ikke min ___, at glasset gik i stykker.'","o":["skyll","skylld","skyld","skylt"],"a":"skyld","r":"Ordet ender på ld med stumt d, ligesom 'guld' og 'kold'."},
{"l":1661,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Du skærer brød med den. Hvilken stavemåde er rigtig?","o":["knif","kniw","kniiv","kniv"],"a":"kniv","r":"Ordet ender på v, selvom det lyder som u. K'et i starten skal også med."},
{"l":1680,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad betyder det at 'løbe tør for' mælk?","o":["at have brugt al mælken","at tørre spildt mælk op fra gulvet","at løbe hen og købe mere mælk","at spilde mælken på bordet"],"a":"at have brugt al mælken","r":"Når man løber tør for noget, er der ikke mere tilbage. Man behøver slet ikke at løbe."},
{"l":1701,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Khadija havde tegnet det flotteste kort over skolen. Hun havde talt alle skridt og målt alle gange. Læreren sagde, at hun var meget grundig.' Hvad betyder 'grundig' her?","o":["At hun arbejder meget hurtigt","At hun gør tingene meget ordentligt","At hun er bedst til at tegne","At hun er glad for sin skole"],"a":"At hun gør tingene meget ordentligt","r":"Hun talte og målte alt. Den, der er grundig, tager sig tid og gør tingene ordentligt."},
{"l":1719,"g":4,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Det var ikke første gang, Karla havde glemt sin gymnastiktaske. Da hun nåede omklædningsrummet, sukkede læreren bare og fandt reservetøjet frem.' Hvad kan man regne ud?","o":["At læreren er glad for hende","At Karla ikke kan lide gymnastik","At Karla tit glemmer sin taske","At Karla får nyt tøj af læreren"],"a":"At Karla tit glemmer sin taske","r":"'Ikke første gang', og at læreren bare sukker, viser, at det sker tit."},
{"l":1739,"g":4,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket ord betyder det modsatte af 'nær', når vi taler om et sted?","o":["lille","ny","tom","fjern"],"a":"fjern","r":"Et nært sted ligger tæt på, og et fjernt sted ligger langt væk."},
{"l":1761,"g":4,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket ord dækker både 'ræv', 'hare' og 'egern'?","o":["vilde dyr","husdyr","insekter","rovdyr"],"a":"vilde dyr","r":"Ræve, harer og egern lever frit i naturen og bliver ikke passet af mennesker. Derfor er de ikke husdyr, og en hare spiser ikke andre dyr."},
{"l":1782,"g":4,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Oskar ventede, indtil mor havde sat sig. Så lagde han tegningen med guldstjernen foran hende og stod og vippede på tæerne.' Hvad tror Oskar, at mor vil sige?","o":["At han skal rydde op","At tegningen er flot","At hun ikke har tid nu","At han tegner for meget"],"a":"At tegningen er flot","r":"Tegningen har fået en guldstjerne, og han vipper spændt på tæerne. Han er stolt og regner med ros."},
{"l":1800,"g":4,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Havet er salt, fordi vand fra floder fører små mængder salt med ud. Når havvand fordamper, bliver saltet tilbage. Over mange millioner år er havet derfor blevet salt.' Hvad sker der med saltet, når havvand fordamper?","o":["Det stiger op med vandet","Det bliver til regn","Det bliver tilbage i havet","Det bliver til is"],"a":"Det bliver tilbage i havet","r":"Teksten siger, at saltet bliver tilbage, når vandet fordamper. Kun vandet stiger op."},
{"l":1821,"g":4,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad føler man, når man er 'lettet'?","o":["at man vejer mindre end før","at man glæder sig til i morgen","at man er vred på en ven","at en bekymring er forsvundet"],"a":"at en bekymring er forsvundet","r":"Man bliver lettet, når noget svært er overstået. Det føles, som om en tung byrde er væk, men vægten er den samme."},
{"l":1841,"g":4,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Det, familien spiser klokken 18. Hvilken stavemåde er rigtig?","o":["aftensmad","avtensmad","aftensmat","aftens mad"],"a":"aftensmad","r":"Ordet skrives i ét ord med f, selvom det kan lyde som v. Slutningen er 'mad'."},
{"l":1860,"g":4,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Sæt det rigtige ord ind: 'Han ___ sin hue under sengen i går.'","o":["fant","fandt","fanndt","fandte"],"a":"fandt","r":"Datid af 'finde' skifter vokal til a. D'et fra 'finde' bliver, og der kommer et t efter."},
{"l":1881,"g":4,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad betyder det at 'give op'?","o":["at række en gave op til nogen","at række hånden i vejret","at holde op med at prøve","at gå op ad en trappe"],"a":"at holde op med at prøve","r":"Den, der giver op, stopper, fordi det virker for svært. Vendingen har ikke noget med gaver at gøre."},
{"l":1899,"g":4,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Lige efter fødslen kan et føl rejse sig op. Efter en time eller to kan det gå og følge sin mor. Et menneskebarn er omkring et år om at lære at gå.' Hvad er forskellen på et føl og et menneskebarn?","o":["Menneskebarnet går før føllet","Føllet er ét år om at gå","De lærer at gå lige hurtigt","Føllet lærer hurtigere at gå"],"a":"Føllet lærer hurtigere at gå","r":"Teksten sammenligner: Føllet kan gå efter et par timer, men menneskebarnet er cirka et år om det."},
{"l":1919,"g":4,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad betyder det, at en cykelpumpe er 'ubrugelig'?","o":["at den ikke kan bruges til noget","at den er helt ny og ubrugt","at man bruger den hver dag","at den kan bruges til mange ting"],"a":"at den ikke kan bruges til noget","r":"Noget ubrugeligt virker ikke til det, det skal. Pas på: 'ubrugt' er noget andet og betyder, at ingen har brugt det endnu."},
{"l":1941,"g":4,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket tillægsord er lavet af navneordet 'sol'?","o":["solgt","solrig","solid","sold"],"a":"solrig","r":"En solrig dag er en dag med meget sol. 'Solgt' kommer af 'sælge', og 'solid' betyder stærk og fast."},
{"l":1959,"g":4,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Havde jeg ikke sagt, at du skulle tage en jakke med? sagde mor. Jakob stod i døren med drivvådt tøj og sagde ingenting.' Hvad kan man slutte om Jakob?","o":["At han havde taget en jakke med","At han var glad for regnen","At han ikke fulgte mors råd","At han havde vasket sit tøj"],"a":"At han ikke fulgte mors råd","r":"Mor havde sagt, han skulle have en jakke med. Hans våde tøj og tavshed viser, at han lod være."},
{"l":1979,"g":4,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad er en 'borger'?","o":["en person, der bor på et slot","en person, der arbejder med at bygge","en person, der sælger mad i en bod","en person, der bor i et land eller en by"],"a":"en person, der bor i et land eller en by","r":"Alle, der bor i en by eller et land, er borgere dér. Man behøver ikke at bo på en borg for at være borger."},
{"l":2002,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad er det modsatte af 'fugtig'?","o":["tør","kold","tung","mørk"],"a":"tør","r":"Noget fugtigt er lidt vådt, og noget tørt har intet vand i sig. Et fugtigt håndklæde kan både være varmt og koldt, så 'kold' er ikke det modsatte."},
{"l":2017,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilket stedord passer: 'Har du set ___ handsker?'","o":["min","mine","mit","mig"],"a":"mine","r":"Handsker er flertal, og foran flertal hedder det 'mine'."},
{"l":2040,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'De fleste planter skal bruge sollys for at vokse. Derfor bøjer planten i vindueskarmen sig mod ruden. Hvis man drejer potten, bøjer den sig langsomt tilbage mod lyset igen.' Hvad sker der, hvis man drejer potten?","o":["Planten begynder at visne","Planten stopper med at vokse","Planten bøjer sig mod lyset igen","Planten vender ryggen til ruden"],"a":"Planten bøjer sig mod lyset igen","r":"Teksten siger, at planten langsomt bøjer sig tilbage mod lyset, fordi den skal bruge sollys."},
{"l":2060,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvilken form passer: 'Du skal ___ på alle spørgsmålene.'","o":["svarer","svarre","svarrer","svare"],"a":"svare","r":"Efter 'skal' står navneform, så der er ingen -r til sidst."},
{"l":2077,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Vælg det rigtige ord: 'Naboerne har fået en hund. ___ hund hedder Bølle.'","o":["Deres","De","Dem","Os"],"a":"Deres","r":"Hunden tilhører naboerne. Når noget tilhører flere, hedder det 'deres'."},
{"l":2100,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad er 'kvalme'?","o":["smerte i den ene fod","følelsen af at skulle kaste op","lysten til at grine højt","trangen til at sove om dagen"],"a":"følelsen af at skulle kaste op","r":"Kvalme mærker man i maven, for eksempel hvis man bliver køresyg."},
{"l":2121,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Holdet havde ikke meget håb. De lå under med to mål, og der var kun fem minutter tilbage. Da fløjten lød, stod der tre-to til dem på tavlen.' Hvad må der være sket?","o":["Modstanderne fik ét mål mere","Dommeren lavede en fejl","De scorede tre mål på fem minutter","Kampen blev afbrudt af regn"],"a":"De scorede tre mål på fem minutter","r":"Hvis de lå under med to, skulle der tre mål til at vinde. Det nåede de på de sidste fem minutter."},
{"l":2137,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket ord passer: 'Efter en uge begyndte frøet at ___ i den våde jord.'","o":["smelte","gnistre","blinke","spire"],"a":"spire","r":"Et frø spirer, når det begynder at vokse og sender en lille plante op."},
{"l":2160,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"En bil er 'rummelig'. Hvad betyder det?","o":["at der er god plads i den","at den kører meget hurtigt","at den larmer ret meget","at den er helt ny og dyr"],"a":"at der er god plads i den","r":"Rummelig kommer af rum. En rummelig bil har god plads til både folk og bagage."},
{"l":2183,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket ord mangler: 'Læs ___ først, så ved du kort, hvad teksten handler om.'","o":["underskriften","overskriften","udskriften","afskriften"],"a":"overskriften","r":"Overskriften står øverst og fortæller, hvad teksten handler om. Underskriften er dit navn, skrevet med din egen hånd."},
{"l":2198,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket ord passer: 'Sanne var syg i tre dage, så hun havde meget ___ i den måned.'","o":["forår","forbrug","fravær","fornuft"],"a":"fravær","r":"Fravær betyder, at man ikke er til stede. Læreren skriver det ned, når en elev ikke er i skole."},
{"l":2220,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Når en isbjørn ligger helt stille ved et hul i isen, venter den på en sæl. Sælen skal op for at trække vejret. Isbjørnen kan vente i mange timer.' Hvad viser teksten, at isbjørnen har meget af?","o":["Fart","Mod","Styrke","Tålmodighed"],"a":"Tålmodighed","r":"Teksten fortæller, at isbjørnen ligger stille i mange timer. At kunne vente så længe kræver tålmodighed."},
{"l":2240,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvad skal der stå på stregen? '___ holder møde efter skole.'","o":["lærerne","lærene","lærerene","lærererne"],"a":"lærerne","r":"Flertal er 'lærere', men i bestemt flertal slutter ordet på -rne."},
{"l":2258,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket navneord hører til tillægsordet 'stor'?","o":["støvregn","størrelse","stormvejr","stilhed"],"a":"størrelse","r":"Hvor stor en ting er, kalder vi dens størrelse. 'Storm' ligner, men kommer ikke af 'stor'."},
{"l":2281,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad gør en 'lovlydig' borger?","o":["taler højt i byen","laver selv nye love","følger landets love","arbejder på rådhuset"],"a":"følger landets love","r":"Den, der er lovlydig, adlyder loven. Ordet handler om at adlyde og ikke om støj."},
{"l":2300,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"Hvad får man typisk at vide i begyndelsen af en fortælling?","o":["Hvordan problemet til sidst bliver løst","Hvem der vinder til allersidst i historien","Hvad der sker i det mest spændende kapitel","Hvem personerne er, og hvor det foregår"],"a":"Hvem personerne er, og hvor det foregår","r":"I begyndelsen møder vi personerne og ser, hvor vi er. Så kan vi følge med i resten af historien."},
{"l":2317,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket ord er det modsatte af 'ankomst' på en togstation?","o":["afgang","perron","billet","rejse"],"a":"afgang","r":"Ved ankomst kommer toget til stationen, og ved afgang kører det derfra. Begge tider står på tavlen."},
{"l":2340,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket ord betyder næsten det samme som 'årsag'?","o":["følge","grund","plan","svar"],"a":"grund","r":"Årsagen til noget er grunden til, at det skete. 'Følge' er det, der sker bagefter."},
{"l":2360,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"Hvad sker der som regel i slutningen af en fortælling?","o":["Personerne bliver præsenteret for læseren","Vi får at vide, hvor historien foregår","Problemet bliver løst på en eller anden måde","Et nyt problem opstår for første gang"],"a":"Problemet bliver løst på en eller anden måde","r":"I midten bliver det spændende, og til sidst finder de en løsning. Personerne og stedet møder vi allerede i begyndelsen."},
{"l":2378,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad er 'formålet' med noget?","o":["det, man måler det med","det, der er sket før","det, man skal betale for det","det, man vil opnå med det"],"a":"det, man vil opnå med det","r":"Formålet er meningen med at gøre noget. Formålet med at øve sig er for eksempel at blive bedre."},
{"l":2400,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad er en 'opfindelse'?","o":["en ny ting, som nogen har fundet på","en ting, man har tabt og fundet igen","en gammel ting fra et museum","en fest for en, der er blevet gammel"],"a":"en ny ting, som nogen har fundet på","r":"En opfindelse er noget nyt, der ikke fandtes før, for eksempel telefonen. Det er ikke det samme som at finde noget, der var væk."},
{"l":2420,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"Hvad må den lille havfrue betale havheksen for at få ben?","o":["sin krone","sin stemme","sit guld","sine perler"],"a":"sin stemme","r":"Havheksen tager havfruens smukke stemme. Derfor kan hun ikke fortælle prinsen, hvem hun er."},
{"l":2438,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket ord mangler: 'I bussen tog Frida ___ til den gamle mand og gav ham sin plads.'","o":["tilløb","fejl","hensyn","tid"],"a":"hensyn","r":"At tage hensyn er at tænke på, hvad andre har brug for. Frida gav sin plads, fordi manden havde mere brug for den."},
{"l":2460,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad betyder det, at en fugl er 'fredet'?","o":["at den er meget rolig af sig","at den kun lever om vinteren","at den er holdt op med at synge","at man ikke må jage den"],"a":"at man ikke må jage den","r":"Fredede dyr er beskyttet af loven. Ordet handler om beskyttelse og ikke om, at fuglen er fredelig."},
{"l":2478,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Sæt det rigtige ord ind: 'Du må ___ gerne låne min blyant.'","o":["selvfølgelig","selfølgelig","selvfølelig","selvføljelig"],"a":"selvfølgelig","r":"Ordet kommer af 'selvfølge' og får endelsen -lig. Både v'et i 'selv' og g'et i 'følge' skal med."},
{"l":2497,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Vælg den rigtige stavemåde: 'En snegl er meget ___.'","o":["lansom","langsom","langsomm","lanksom"],"a":"langsom","r":"Ordet består af 'lang' og endelsen -som. G'et skal med, og der er ét m."},
{"l":2520,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad betyder det at 'få kolde fødder'?","o":["at fryse, fordi man har glemt sine sokker","at gå ud i sneen uden sko på","at blive bange og alligevel ikke turde","at gå meget langsomt hjem fra skole"],"a":"at blive bange og alligevel ikke turde","r":"Den, der får kolde fødder, ville gerne gøre noget, men trækker sig i sidste øjeblik."},
{"l":2540,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"Læs: 'Jeg er en lille mus, der bor under jeres køkkenbord.' En voksen kvinde har skrevet historien. Hvem er jeg-fortælleren?","o":["forfatteren","læseren","køkkenbordet","musen"],"a":"musen","r":"Forfatter og fortæller er ikke det samme. Kvinden har skrevet teksten, men det er musen, der siger 'jeg'."},
{"l":2558,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket navneord hører til udsagnsordet 'tænke'?","o":["tanke","tank","tand","tante"],"a":"tanke","r":"Det, man tænker, er en tanke. En tank er en stor beholder og er et helt andet ord."},
{"l":2581,"g":4,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad er det modsatte af 'overflødig'?","o":["flydende","nødvendig","tydelig","sjælden"],"a":"nødvendig","r":"Noget overflødigt kan man godt undvære, mens man ikke kan klare sig uden noget nødvendigt. Ordet handler ikke om væske."},
{"l":2596,"g":4,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket ord betyder næsten det samme som 'gavmild'?","o":["stædig","ærlig","generøs","nervøs"],"a":"generøs","r":"En gavmild person giver gerne til andre, ligesom en generøs person. Ordet kommer af 'gave' og 'mild'."},
{"l":2618,"g":4,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad betyder det, at der er 'flertal' for en idé i klassen?","o":["at præcis halvdelen er for den","at alle i klassen er for den","at kun læreren er for den","at over halvdelen er for den"],"a":"at over halvdelen er for den","r":"Ved en afstemning med ja eller nej har flertallet over halvdelen af stemmerne. Det behøver ikke at være alle."},
{"l":2640,"g":4,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Hvis alle tager cyklen i stedet for bilen på korte ture, bliver luften renere, og vi får mere motion. Det koster ingenting og er sjovt. Så hvorfor ikke prøve i morgen?' Hvad vil teksten have læseren til?","o":["At cykle mere","At sælge sin bil","At løbe mere","At købe en ny cykel"],"a":"At cykle mere","r":"Teksten nævner fordele ved cyklen og opfordrer til sidst læseren til at prøve."},
{"l":2658,"g":4,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Den larmende maskine, der gør tæpper og gulve rene. Vælg den rigtige stavemåde.","o":["støvsuer","støvsuger","støvsugger","støv suger"],"a":"støvsuger","r":"Ordet består af 'støv' og 'suger' og skrives i ét ord. Der er ét g."},
{"l":2677,"g":4,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Rummet med bruser og håndvask. Hvilken stavemåde er rigtig?","o":["badeværrelse","baderværelse","badeværelse","bade værelse"],"a":"badeværelse","r":"Ordet består af 'bade' og 'værelse' og skrives i ét ord med ét r."},
{"l":2701,"g":4,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad har man, hvis man har god 'selvtillid'?","o":["en mistanke til alle sine venner","en evne til at holde på hemmeligheder","en masse penge stående i banken","en tro på, at man kan klare noget"],"a":"en tro på, at man kan klare noget","r":"Selvtillid betyder at have tillid til sig selv. Det gør det lettere at prøve noget nyt."},
{"l":2717,"g":4,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad passer bedst: 'Løberen skulle over flere ___ på vej mod målet.'","o":["forhindringer","forbindelser","forandringer","forklaringer"],"a":"forhindringer","r":"En forhindring er noget, der er i vejen, for eksempel et hegn, som løberen skal over."},
{"l":2739,"g":4,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad vil det sige at være 'dristig'?","o":["at blive meget hurtigt træt om aftenen","at turde gøre noget, der er lidt farligt","at tale meget højt i et stille rum","at huske at rydde op efter sig selv"],"a":"at turde gøre noget, der er lidt farligt","r":"En dristig person tør noget, som andre holder sig fra, selvom det kan gå galt."},
{"l":2761,"g":4,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Alle fire ord er skrevet med småt her. Hvilket skal skrives med stort midt i en sætning?","o":["fredag","februar","frederikshavn","fransk"],"a":"frederikshavn","r":"Frederikshavn er en by og et egennavn. Ugedage, måneder og sprog skrives med småt på dansk."},
{"l":2777,"g":4,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad betyder ordet 'tilsyneladende'?","o":["sådan som det altid har været","sådan som man har lært det","sådan som læreren har sagt","sådan som det ser ud til at være"],"a":"sådan som det ser ud til at være","r":"Noget tilsyneladende ser ud på en bestemt måde, men det er ikke sikkert, at det er sådan. Ordet hænger sammen med 'syn'."},
{"l":2800,"g":4,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad betyder det at have 'en høne at plukke' med nogen?","o":["at have noget at skændes med dem om","at have noget at fejre sammen med dem","at have et måltid at lave sammen med dem","at have noget at købe af dem i butikken"],"a":"at have noget at skændes med dem om","r":"Har du en høne at plukke med nogen, er der noget, du er utilfreds med og vil tale med dem om."},
{"l":2820,"g":4,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Far og Ea flyttede sofaen for at gøre rent. Under den var gulvet meget mørkere end i resten af stuen, hvor solen skinnede ind hver dag.' Hvad fortæller det mørke stykke gulv?","o":["At nogen lige har malet gulvet","At sofaen har stået der i lang tid","At gulvet er meget beskidt","At solen skinner for meget"],"a":"At sofaen har stået der i lang tid","r":"Solen gør gulvet lysere lidt efter lidt. Under sofaen kom solen ikke hen, så den må have stået der længe."},
{"l":2838,"g":4,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Da Johanne havde vundet, sagde hun tak til sin træner og til de andre piger. Bagefter gik hun hen til Nanna, som havde tabt, og satte sig ved siden af hende uden at sige noget.' Hvorfor sætter Johanne sig hos Nanna?","o":["For at vise, at hun har vundet","For at spørge om noget","For at trøste hende","For at hvile sig lidt"],"a":"For at trøste hende","r":"Nanna har tabt, og Johanne sætter sig stille hos hende. Man kan godt trøste uden at sige noget."},
{"l":2860,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad kaldes dyr som hjorte, køer og harer, der ikke spiser kød?","o":["rovdyr","altædere","nedbrydere","planteædere"],"a":"planteædere","r":"Planteædere lever af græs, blade og andre planter. Rovdyr spiser kød, og altædere spiser både planter og kød."},
{"l":2880,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Kære forældre i 5.B. På fredag tager vi til stranden for at undersøge dyr i vandet. Eleverne skal have gummistøvler, madpakke og tøj efter vejret med. Vi mødes ved skolen klokken 8.15 og er tilbage klokken 13. Venlig hilsen Lene og Murat' Hvorfor har lærerne skrevet beskeden?","o":["For at fortælle, hvad der skal ske, og hvad eleverne skal have med","For at bede forældrene om at køre eleverne til stranden","For at fortælle, hvilke dyr der lever i vandet ved stranden","For at bede forældrene om at tage med på turen til stranden"],"a":"For at fortælle, hvad der skal ske, og hvad eleverne skal have med","r":"Beskeden giver praktiske oplysninger om tid, sted og udstyr. Det er formålet med et brev hjem til forældrene."},
{"l":2898,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Alberte havde bagt muffins til hele klassen, men de var blevet helt flade. Hun stod med bakken og kiggede ned i den. Så tog Oskar en muffin og tyggede længe. – Jeg kan bedst lide dem, der er flade, sagde han og blinkede til hende.' Hvorfor siger Oskar det?","o":["Han kan bedst lide flade kager","Han vil gerne gøre Alberte glad igen","Han vil have en muffin mere bagefter","Han synes, at hun skal øve sig på at bage"],"a":"Han vil gerne gøre Alberte glad igen","r":"Alberte er ked af, at hendes muffins er flade. Oskar blinker til hende, så han siger det for at muntre hende op."},
{"l":2916,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Vores skole har fået et nyt legeområde. Der er en klatrevæg og to gynger. Klatrevæggen er skolens sjoveste sted. Området åbner for alle elever på mandag.' Hvilken sætning er en holdning og ikke et faktum?","o":["Vores skole har fået et nyt legeområde","Der er en klatrevæg og to gynger","Klatrevæggen er skolens sjoveste sted","Området åbner for alle elever på mandag"],"a":"Klatrevæggen er skolens sjoveste sted","r":"Hvad der er sjovest, er en mening, som andre kan være uenige i. De andre sætninger kan man kontrollere."},
{"l":2937,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Sæt ind i sætningen: 'Ida ___ rigtigt på alle spørgsmålene i dag.'","o":["svarrer","svar","svare","svarer"],"a":"svarer","r":"Ida gør det nu, så ordet står i nutid og ender på -er. Inde i ordet står der kun ét r."},
{"l":2959,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvilken form skal der stå? 'Hver lørdag ___ mor friske rundstykker hos bageren.'","o":["køber","købber","købe","køper"],"a":"køber","r":"Det er noget, der sker hver lørdag, så det er nutid med r til sidst. Ø'et er langt, så der er kun ét b."},
{"l":2979,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilken sætning om Viktors cykeltur har kommaet det rigtige sted?","o":["Da Viktor nåede toppen, af bakken stoppede han.","Da Viktor nåede toppen af bakken, stoppede han.","Da Viktor nåede toppen af bakken stoppede, han.","Da Viktor nåede, toppen af bakken stoppede han."],"a":"Da Viktor nåede toppen af bakken, stoppede han.","r":"Hele 'Da Viktor nåede toppen af bakken' er ledsætningen. Kommaet må først komme, når den er helt færdig."},
{"l":2997,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Ali og hans far byggede en fuglekasse. Far savede, og Ali holdt brædderne. Da den skulle sættes op, valgte Ali et træ langt fra vejen og fra naboens kat. – Her får de ro, sagde han.' Hvorfor vælger Ali netop det træ?","o":["Det er det højeste træ i haven","Far har sagt, at det skal være der","Han vil passe på fuglene","Træet er nemt at se fra hans vindue"],"a":"Han vil passe på fuglene","r":"Han vælger et sted væk fra vej og kat og siger, at fuglene får ro. Det viser, at han tænker på deres tryghed."},
{"l":3015,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Fatima har gået til svømning i tre år. Hun træner to gange om ugen i Søhallen. Svømning er den bedste sport i verden. I marts vandt hun en bronzemedalje i crawl.' Hvilken sætning kan andre med god grund være uenige i?","o":["Fatima har gået til svømning i tre år","Hun træner to gange om ugen i Søhallen","I marts vandt hun en bronzemedalje i crawl","Svømning er den bedste sport i verden"],"a":"Svømning er den bedste sport i verden","r":"Det er en holdning. De andre sætninger er oplysninger, som man kan undersøge."},
{"l":3036,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilket forholdsord passer i sætningen: 'Hele klassen er interesseret ___ dinosaurer.'","o":["i","af","på","for"],"a":"i","r":"Man er interesseret i noget: interesseret i dyr, interesseret i fodbold. Den slags ordpar er faste, og dem må man lære udenad."},
{"l":3055,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilken sætning om bageren mangler et komma?","o":["Om morgenen køber vi boller.","Når bageren åbner køber vi boller.","Bageren åbner tidligt om morgenen.","Vi køber boller hos bageren."],"a":"Når bageren åbner køber vi boller.","r":"'Når bageren åbner' er en ledsætning, der står først, og den skal efterfølges af komma. De andre sætninger har ingen ledsætning."},
{"l":3077,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad er meningen med ordsproget 'Smag og behag er forskellige'?","o":["Mad smager forskelligt fra dag til dag","Man skal smage på alting, før man siger nej","Folk kan lide forskellige ting","Det er uhøfligt at tale om maden"],"a":"Folk kan lide forskellige ting","r":"Behag betyder det, man synes om. Ordsproget minder os om, at ikke alle synes om det samme, og at det er i orden."},
{"l":3093,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Efter hvilket ord skal kommaet stå: 'Hvis toget fra Odense er forsinket i morgen ringer jeg til dig.'?","o":["Odense","forsinket","ringer","morgen"],"a":"morgen","r":"'i morgen' hører med til ledsætningen, som begynder med 'Hvis'. Hovedsætningen begynder først med 'ringer'."},
{"l":3114,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'I alle grønne planter sker der noget vigtigt. Med hjælp fra sollys laver planterne sukker af vand og luft. Sukkeret er deres føde. Samtidig sender de ilt ud, som mennesker og dyr skal bruge for at trække vejret.' Hvorfor kan en plante ikke klare sig uden lys?","o":["Den kan ikke lave sin føde","Den kan ikke optage vand","Den bliver for kold om natten","Den får for meget ilt"],"a":"Den kan ikke lave sin føde","r":"Teksten siger, at planten bruger sollys til at lave sukker, som er dens føde. Uden lys mangler den altså føde."},
{"l":3135,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Vælg datid: 'Hun ___ sig på bænken og tog sin madpakke frem.'","o":["sad","satte","sattede","sætted"],"a":"satte","r":"Hun flyttede sig selv, så ordet er 'sætte sig'. I datid skifter æ til a."},
{"l":3157,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilken tid står sætningen i: 'Mads har vasket bilen.'","o":["datid","nutid","førnutid","førdatid"],"a":"førnutid","r":"'Har' plus tillægsform giver førnutid. Det er sket, men vi kan se det nu: Bilen er ren."},
{"l":3179,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvad skal der stå? 'Hvem har ___ de våde støvler midt i gangen?'","o":["siddet","satte","sad","sat"],"a":"sat","r":"Nogen har flyttet støvlerne, så ordet kommer af 'sætte'. Efter 'har' hedder det 'sat' med ét t."},
{"l":3197,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket ord passer: 'Vinduesglas er ___, så lyset kan slippe ind.'","o":["gennemsigtigt","bøjeligt","opløseligt","magnetisk"],"a":"gennemsigtigt","r":"Et gennemsigtigt materiale lader lys slippe igennem, så man kan se, hvad der er på den anden side."},
{"l":3217,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Hver aften satte Alma en skål mælk ud til den vilde kat. Den første uge kom katten først, når hun var gået ind. Den anden uge blev den ved skålen, mens hun så på. I dag gned den sig op ad hendes ben.' Hvad viser teksten om katten?","o":["At den er meget sulten efter en lang vinter","At den langsomt er blevet tryg ved Alma","At den vil have Alma til at gå ind igen","At den kun kommer for at få mælk"],"a":"At den langsomt er blevet tryg ved Alma","r":"Teksten viser en udvikling trin for trin: Katten kommer tættere og tættere på. Det betyder, at den stoler mere på hende."},
{"l":3235,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad er et 'kloster'?","o":["et stort hus, hvor kongen holder sine fester","en by med mure og tårne ved en grænse","et sted, hvor munke eller nonner lever sammen","en skole for unge riddere og deres heste"],"a":"et sted, hvor munke eller nonner lever sammen","r":"I middelalderens klostre boede munke og nonner. De bad, arbejdede og skrev ofte bøger af i hånden."},
{"l":3256,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Find den rigtige form: 'Uret ___ halv tre.'","o":["vidser","hviser","visser","viser"],"a":"viser","r":"Ordet kommer af 'at vise'. Det har hverken h eller d, og nutid ender på -er."},
{"l":3278,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvad er grundleddet: 'Bagefter kørte vi hjem i bilen.'","o":["vi","Bagefter","kørte","i bilen"],"a":"vi","r":"Spørg: Hvem kørte? Det gjorde 'vi'. 'Bagefter' står først, men er ikke den, der handler."},
{"l":3295,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad betyder det, at vejret er 'ustadigt'?","o":["Det er koldt hele dagen","Det skifter hele tiden","Det bliver snart sommer","Det regner slet ikke i dag"],"a":"Det skifter hele tiden","r":"Noget, der er stadigt, bliver ved med at være det samme. Ustadigt vejr gør det modsatte: Det kan regne det ene øjeblik og være sol det næste."},
{"l":3311,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Find forholdsordet: 'Lampen hænger over spisebordet.'","o":["hænger","lampen","over","spisebordet"],"a":"over","r":"'Over' viser lampens plads i forhold til spisebordet. Det er et forholdsord."}
]$$::jsonb) AS e
JOIN (VALUES
